/**
 * pipeline/phase-b/confidence-gate.ts — 置信度元数据门控
 *
 * 实现 AR-08 的 Confidence-tier 方案（Gate #7）：
 *
 * 核心原则（取自 AR-08 §特别警告）：
 *   必须先让 rule-checker 产出独立置信度元数据——LLM 自评的 confidence
 *   字段目前是推导赋值，不是真验证。在此基础上再做门控。
 *
 * 工作流程：
 *   1. 接收 Phase B 产出的 PersonaGenomeBlue[]（含 LLM 自评 confidence）
 *   2. 对每个 mentalModel 执行独立置信度再评估（基于框架来源、抽象级、语义完整性）
 *   3. 输出 ConfidenceMetadata[]（独立于 LLM 自评的第三方元数据）
 *   4. 对 TOTAL CONFIDENCE < 0.4 的基因组标注 degradeMarker
 *
 * @packageDocumentation
 */
import type { PersonaGenomeBlue } from '../../types';
/**
 * 单条心智模型的置信度元数据（rule-checker 独立产出，不依赖 LLM 自评）
 */
export interface MentalModelConfidence {
    /** 框架来源类型 */
    sourceType: 'known_framework' | 'general_pattern' | 'llm_invented' | 'empty';
    /** 抽象等级 */
    abstractionLevel: 'concrete' | 'moderate' | 'abstract';
    /** 语义完整性评分 (0-1) */
    semanticScore: number;
    /** 独立置信度 (0-1) — 融合上述三项的加权结果 */
    independentConfidence: number;
    /** 信用评估说明 */
    rationale: string;
}
/**
 * 单个角色基因组的置信度元数据
 */
export interface GenomeConfidenceMetadata {
    roleId: string;
    roleName: string;
    /** LLM 自评置信度（原始输入） */
    llmSelfConfidence: number;
    /** 规则校验器独立评估的置信度 */
    ruleCheckerConfidence: number;
    /** 每个 mentalModel 的独立置信度 */
    mentalModelConfidences: MentalModelConfidence[];
    /** 是否标记为降级 */
    isDegraded: boolean;
    /** 降级原因（如降级） */
    degradeReason?: string;
}
/**
 * 置信度门控总体输出
 */
export interface ConfidenceGateOutput {
    genomes: Array<{
        genome: PersonaGenomeBlue;
        metadata: GenomeConfidenceMetadata;
    }>;
    /** 全局是否有任意基因组被降级 */
    anyDegraded: boolean;
    /** 降级条目清单 */
    degradedEntries: Array<{
        roleId: string;
        roleName: string;
        reason: string;
    }>;
}
/**
 * 主入口：对 Phase B 产出的 genome 执行独立置信度再评估
 *
 * @param personaGenomes - Phase B 产出的角色基因组列表
 * @returns 置信度门控输出，包含每条约目的元数据和降级标记
 */
export declare function evaluateConfidence(personaGenomes: PersonaGenomeBlue[]): ConfidenceGateOutput;
/**
 * 快速判断：当前基因组是否建议注入 prompt（基于独立置信度）
 *
 * confidenceTier 映射：
 *   high   = 独立置信度 ≥ 0.7 → 正常注入
 *   medium = 独立置信度 0.4-0.7 → 可注入，建议标注"中等置信"
 *   low    = 独立置信度 < 0.4 → 不建议注入（或仅注入 name，跳过 application）
 */
export declare function getConfidenceTier(ruleCheckerConfidence: number): 'high' | 'medium' | 'low';
